--
-- Table structure for table `missions`
--

DROP TABLE IF EXISTS `missions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `missions` (
  `Mission_ID` int NOT NULL AUTO_INCREMENT,
  `Mission_Name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Description` text COLLATE utf8mb4_unicode_ci,
  `Target_Merchant_ID` int NOT NULL,
  `Max_Recipients` int DEFAULT NULL,
  `Start_DateTime` datetime NOT NULL,
  `End_DateTime` datetime NOT NULL,
  `Status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Daily_Analysis_ID` int DEFAULT NULL,
  `Campaign_Week_Start` date DEFAULT NULL,
  `Daily_Start_Minute` int DEFAULT NULL,
  `Daily_End_Minute` int DEFAULT NULL,
  `Selection_Evidence` json DEFAULT NULL,
  `Ai_Daily_Stamp_Limit` int DEFAULT NULL,
  PRIMARY KEY (`Mission_ID`),
  UNIQUE KEY `uq_mission_daily_analysis` (`Daily_Analysis_ID`),
  KEY `fk_mission_merchant` (`Target_Merchant_ID`),
  KEY `idx_mission_merchant_campaign_week` (`Target_Merchant_ID`,`Campaign_Week_Start`),
  CONSTRAINT `fk_mission_daily_analysis` FOREIGN KEY (`Daily_Analysis_ID`) REFERENCES `daily_mission_analyses` (`Analysis_ID`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_mission_merchant` FOREIGN KEY (`Target_Merchant_ID`) REFERENCES `merchants` (`Mch_ID`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=313 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

