INSERT INTO `missions` VALUES (1,'กินข้าวมันไก่ครบ 5 จาน',NULL,1,100,'2026-01-01 00:00:00','2026-12-31 23:59:59','ACTIVE',NULL,NULL,NULL,NULL,NULL,NULL),(2,'ซื้อกาแฟ 10 แก้ว',NULL,2,50,'2026-01-01 00:00:00','2026-12-31 23:59:59','ACTIVE',NULL,NULL,NULL,NULL,NULL,NULL),(3,'ช่วงเวลาขายต่ำสุด','ช่วงเวลา 14:00-16:00 ที่มีการขายต่ำสุดในวันธรรมดา ซึ่งมีการซื้อเพียง 1 ครั้ง ทำให้เป็นช่วงเวลาที่เหมาะสมสำหรับการส่งเสริมการขายเพิ่มขึ้น',12,50,'2026-10-26 07:00:00','2026-10-26 09:00:00','ACTIVE',59,NULL,NULL,NULL,NULL,NULL),(4,'ช่วยอุดหนุนครัวบ้านพระนคร กรุงเทพมหานคร','ชวนอุดหนุนครัวบ้านพระนคร กรุงเทพมหานครในช่วง 14:00–16:00 น. ยอดขายเฉลี่ยต่อวันที่มีบิลลดลง 64% จากช่วงอ้างอิง',22,NULL,'2026-10-25 17:00:00','2026-11-01 17:00:00','INACTIVE',NULL,'2026-10-26',840,960,'{\"ratio\": 0.3628318584070797, \"analyzedAt\": \"2026-10-28T11:51:19.326Z\", \"recentDaily\": 205, \"referenceDaily\": 565}',NULL),(5,'ช่วยอุดหนุนของดีชุมชนดุสิต กรุงเทพมหานคร','ชวนอุดหนุนของดีชุมชนดุสิต กรุงเทพมหานครในช่วง 16:00–18:00 น. ยอดขายเฉลี่ยต่อวันที่มีบิลลดลง 63% จากช่วงอ้างอิง',23,NULL,'2026-10-25 17:00:00','2026-11-01 17:00:00','INACTIVE',NULL,'2026-10-26',960,1080,'{\"ratio\": 0.3658536585365854, \"analyzedAt\": \"2026-10-28T11:51:19.326Z\", \"recentDaily\": 225, \"referenceDaily\": 615}',NULL),(6,'ช่วยอุดหนุนครัวบ้านเมืองนครปฐม นครปฐม','ชวนอุดหนุนครัวบ้านเมืองนครปฐม นครปฐมในช่วง 14:00–16:00 น. ยอดขายเฉลี่ยต่อวันที่มีบิลลดลง 64% จากช่วงอ้างอิง',138,NULL,'2026-10-25 17:00:00','2026-11-01 17:00:00','INACTIVE',NULL,'2026-10-26',840,960,'{\"ratio\": 0.3628318584070797, \"analyzedAt\": \"2026-10-28T11:51:19.326Z\", \"recentDaily\": 205, \"referenceDaily\": 565}',NULL),(7,'ภารกิจชวนอุดหนุนร้านชุมชนของดีชุมชนกำแพงแสน','ร้านของดีชุมชนกำแพงแสน ในจังหวัดนครปฐม พบว่ายอดขายเฉลี่ยลดลง 63% ช่วงเวลา 16:00-18:0 น. ห้ามสัญญาส่วนลด โควต้า หรือยอดซื้อขั้นต่ำ ช่วยสนับสนุนร้านให้กลับสู่ความสำเร็จได้ด้วยการอุดหนุนร้านในช่วงเวลาที่กำหนด',139,NULL,'2026-10-25 17:00:00','2026-11-01 17:00:00','INACTIVE',NULL,'2026-10-26',960,1