--
-- Table structure for table `sales_transactions`
--

DROP TABLE IF EXISTS `sales_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_transactions` (
  `Tx_ID` bigint NOT NULL AUTO_INCREMENT,
  `User_ID` int NOT NULL,
  `Merchant_ID` int NOT NULL,
  `Total_Amount` decimal(12,2) NOT NULL,
  `User_Paid_Amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `Gov_Subsidized_Amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `Tx_Timestamp` datetime NOT NULL,
  `District_ID` int NOT NULL,
  `Status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Stamp_Paid_Amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`Tx_ID`),
  KEY `fk_transaction_district` (`District_ID`),
  KEY `fk_transaction_merchant` (`Merchant_ID`),
  KEY `fk_transaction_user` (`User_ID`),
  CONSTRAINT `fk_transaction_district` FOREIGN KEY (`District_ID`) REFERENCES `districts` (`Dist_ID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_transaction_merchant` FOREIGN KEY (`Merchant_ID`) REFERENCES `merchants` (`Mch_ID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_transaction_user` FOREIGN KEY (`User_ID`) REFERENCES `users` (`User_ID`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8000175000207527 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

