DROP TABLE IF EXISTS `wallets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wallets` (
  `Wallet_ID` int NOT NULL AUTO_INCREMENT,
  `User_ID` int DEFAULT NULL,
  `Balance` decimal(12,2) NOT NULL DEFAULT '0.00',
  `Status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `Updated_At` datetime NOT NULL,
  `Merchant_ID` int DEFAULT NULL,
  PRIMARY KEY (`Wallet_ID`),
  UNIQUE KEY `User_ID` (`User_ID`),
  UNIQUE KEY `Merchant_ID` (`Merchant_ID`),
  CONSTRAINT `fk_wallet_merchant` FOREIGN KEY (`Merchant_ID`) REFERENCES `merchants` (`Mch_ID`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_wallet_user` FOREIGN KEY (`User_ID`) REFERENCES `users` (`User_ID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=209 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
